 "// A hint is a second, smaller line under the label, for a label that needs it.\nconst SECTIONS: { id: PreferencesSection; label: string; hint?: string; icon: string }[] = [\n  { id: 'account', label: 'Account', icon: 'user' },\n  { id: 'agent', label: 'BYOAI', hint: 'Bring Your Own AI', icon: 'bot' },"),
("""            <span className={`jp-icon jp-icon-${entry.icon}`} aria-hidden="true" />
            <span>{entry.label}</span>""",
"""            <span className={`jp-icon jp-icon-${entry.icon}`} aria-hidden="true" />
            {entry.hint ? (
              <span className="prefs-nav-copy" aria-label={`${entry.label}, ${entry.hint}`}>
                <span>{entry.label}</span>
                <span className="prefs-nav-hint">{entry.hint}</span>
              </span>
            ) : (
              <span>{entry.label}</span>
            )}"""),
